import time
from collections import OrderedDict


class LRUCache:
    def __init__(self, capacity, ttl=None, clock=time.monotonic):
        if capacity < 1:
            raise ValueError("capacity must be >= 1")
        self.capacity = capacity
        self.ttl = ttl
        self.clock = clock
        self._data = OrderedDict()  # key -> (value, deadline or None)

    def _deadline(self):
        if self.ttl is None:
            return None
        return self.clock() + self.ttl

    def _expired(self, deadline):
        return deadline is not None and self.clock() >= deadline

    def _purge_expired(self):
        if self.ttl is None:
            return
        now = self.clock()
        dead = [k for k, (_, d) in self._data.items() if d is not None and now >= d]
        for k in dead:
            del self._data[k]

    def get(self, key, default=None):
        try:
            value, deadline = self._data[key]
        except KeyError:
            return default
        if deadline is not None and self.clock() >= deadline:
            del self._data[key]
            return default
        self._data.move_to_end(key)
        return value

    def put(self, key, value):
        self._purge_expired()
        self._data[key] = (value, self._deadline())
        self._data.move_to_end(key)
        while len(self._data) > self.capacity:
            self._data.popitem(last=False)

    def __len__(self):
        if self.ttl is None:
            return len(self._data)
        now = self.clock()
        return sum(1 for _, d in self._data.values() if d is None or now < d)

    def __contains__(self, key):
        try:
            _, deadline = self._data[key]
        except KeyError:
            return False
        return deadline is None or self.clock() < deadline
```

